func TestConvergenceGuard_EscalatesAfterTwoFailedCycles(t *testing.T) {
	run := runJudgeFailPath(t, nil, 2, nil)
	if got := run.raisedItemType(); got != "acceptance_stuck" { t.Fatalf(...) }
	if !strings.Contains(run.itemInsert(), "'needs_human_review'") { t.Errorf(...) }
	if created, _ := run.out["improve_tool_created"].(bool); created { t.Errorf("no improve_tool item may be raised when escalating") }
	if strings.Contains(run.note, "Fix: improve_tool item created") { t.Errorf("note still claims a fix was queued") }
}
